    ORD = {1: "1.", 2: "2.", 3: "3.", 4: "4."}

    def tr3(n):
        h, r = divmod(n, 100)
        t, o = divmod(r, 10)
        w = []
        if h:
            w.append("yüz" if h == 1 else ONES[h] + " yüz")
        if t:
            w.append(TENS[t])
        if o:
            w.append(ONES[o])
        return " ".join(w)

    def tr_words(n):
        n = int(n)
        if n == 0:
            return "sıfır"
        parts = []
        for val, name in ((10**9, "milyar"), (10**6, "milyon"), (1000, "bin")):
            q, n = divmod(n, val)
            if q:
                if val == 1000 and q == 1:
                    parts.append("bin")
                else:
                    parts.append(tr3(q) + " " + name)
        if n:
            parts.append(tr3(n))
        return " ".join(parts)

    def split_amt(x):
        c = int(round(abs(float(x)) * 100))
        return c // 100, c % 100

    def amt(x, cur):
        """Amount in words with the full currency name (rule 25)."""
        m, k = split_amt(x)
        if cur == "TL":
            return tr_words(m) + " Türk Lirası" if k == 0 else tr_words(m) + " lira " + tr_words(k) + " kuruş"
        if cur == "USD":
            return tr_words(m) + " Dolar" if k == 0 else tr_words(m) + " dolar " + tr_words(k) + " sent"
        if cur == "EUR":
            return tr_words(m) + " Euro" if k == 0 else tr_words(m) + " Euro " + tr_words(k) + " sent"
        return tr_words(m) + " İngiliz Sterlini" if k == 0 else tr_words(m) + " İngiliz Sterlini " + tr_words(k) + " peni"

    def cop(word):
        """The copula suffix (-dır/-dir/-dur/-dür, -tır...) for the last word, Turkish vowel harmony."""
        w = word.lower().replace("İ", "i")
        vow = [ch for ch in w if ch in "aeıioöuü"]
        v = vow[-1] if vow else "e"
        x = {"a": "ı", "ı": "ı", "e": "i", "i": "i", "o": "u", "u": "u", "ö": "ü", "ü": "ü"}[v]
        d = "t" if w and w[-1] in "çfhkpsşt" else "d"
        return d + x + "r"

    def amt_cop(x, cur):
        s = amt(x, cur)
        last = s.split()[-1]
        apo = "'" if last[:1].isupper() else ""
        return s + apo + cop(last)

    def pdate(s):
        try:
            d, m, y = str(s).strip().split(".")
            return datetime.date(int(y), int(m), int(d))
        except Exception:
            return None

    def tdate(d):
        return "%d %s %d" % (d.day, AYLAR[d.month - 1], d.year) if d else ""

    def tdate_cop(d):
        y = d.year % 100
        last = tr_words(d.year).split()[-1] if y else tr_words(d.year).split()[-1]
        return tdate(d) + "'" + cop(last)

    def digits_tr(s):
        return " ".join(DIG[int(c)] for c in str(s) if c.isdigit())

    def today_of(vars):
        n = parse_now(vars.get("now"))
        return n.date() if n else None


    t = today_of(vars)
    vars["today_iso"] = t.isoformat() if t else ""
