                day = _UNITS[w]
                used.add(i)
                break
    year = _year([w for i, w in enumerate(rest) if i not in used]) or default_year
    if not (day and year):
        return ""
    try:
        return datetime.date(int(year), mo, day).isoformat()
    except Exception:
        return ""

try:

    ONES = ["", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
